import{_ as l,c as i,o as n,j as e,af as o,a as s,t as r}from"./chunks/framework.W5ZyBR1w.js";const S=JSON.parse('{"title":"新手教程（？）","description":"本章主要讲述首次接入 MSST-Net 的基本流程。","frontmatter":{"title":"新手教程（？）","description":"本章主要讲述首次接入 MSST-Net 的基本流程。"},"headers":[],"relativePath":"connect/start.md","filePath":"connect/start.md"}'),c={name:"connect/start.md"},p={id:"frontmatter-title",tabindex:"-1"};function h(t,a,d,f,m,b){return n(),i("div",null,[e("h1",p,[s(r(t.$frontmatter.title)+" ",1),a[0]||(a[0]=e("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),e("p",null,r(t.$frontmatter.description),1),a[1]||(a[1]=o('<h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h2><p>首次接入 MSST-Net 的流程如下：</p><ol><li>安装客户端</li><li>完成接入认证</li><li>选择接入方式</li><li>验证连接状态</li></ol><p>如果您是首次使用，建议按本章顺序完成操作。</p><hr><h2 id="第一步-安装客户端" tabindex="-1">第一步：安装客户端 <a class="header-anchor" href="#第一步-安装客户端" aria-label="Permalink to “第一步：安装客户端”">​</a></h2><p>请先完成客户端安装。</p><p>安装说明请参考：</p><p><a href="/connect/install/client">《安装部署 / 安装客户端》</a></p><p>如果需要开机自动运行：</p><p><a href="/connect/install/service">《安装部署 / 配置系统服务》</a></p><p>如果需要选择控制器版本：</p><p><a href="/connect/install/controller">《安装部署 / 控制器说明》</a></p><hr><h2 id="第二步-完成接入认证" tabindex="-1">第二步：完成接入认证 <a class="header-anchor" href="#第二步-完成接入认证" aria-label="Permalink to “第二步：完成接入认证”">​</a></h2><p>自 2026 年 6 月 15 日起，接入 MSST-Net 前必须完成接入认证。</p><h3 id="已有账号" tabindex="-1">已有账号 <a class="header-anchor" href="#已有账号" aria-label="Permalink to “已有账号”">​</a></h3><p>如果您已经持有 MSST 联合认证平台账号：</p><p>打开客户端控制器，进入 <strong>接入认证</strong> 页面，并按照提示完成认证。</p><h3 id="尚未注册账号" tabindex="-1">尚未注册账号 <a class="header-anchor" href="#尚未注册账号" aria-label="Permalink to “尚未注册账号”">​</a></h3><p>如果您尚未持有账号：</p><p>请填写 <strong>MSST-Net 接入登记表</strong>。</p><p>审核通过后，管理员会将账号信息发送至您提供的联系方式。</p><hr><h2 id="第三步-选择接入方式" tabindex="-1">第三步：选择接入方式 <a class="header-anchor" href="#第三步-选择接入方式" aria-label="Permalink to “第三步：选择接入方式”">​</a></h2><p>完成认证后，选择一种接入方式：</p><h3 id="大内网模式" tabindex="-1">大内网模式 <a class="header-anchor" href="#大内网模式" aria-label="Permalink to “大内网模式”">​</a></h3><p>适用于长期稳定接入统一网络环境。</p><p>详见：</p><p><a href="/connect/spaces/network_space">《大内网模式》</a></p><h3 id="房间模式" tabindex="-1">房间模式 <a class="header-anchor" href="#房间模式" aria-label="Permalink to “房间模式”">​</a></h3><p>适用于临时组网或小范围协作。</p><p>详见：</p><p><a href="/connect/spaces/room_space">《房间模式》</a></p><hr><h2 id="第四步-验证连接状态" tabindex="-1">第四步：验证连接状态 <a class="header-anchor" href="#第四步-验证连接状态" aria-label="Permalink to “第四步：验证连接状态”">​</a></h2><p>完成接入后，建议进行基础验证：</p><ul><li>检查设备是否上线</li><li>检查网络连接状态</li><li>测试房间加入功能</li><li>测试基础通信功能</li></ul><p>如遇问题：</p><p><a href="/connect/faq">《常见问题》</a></p><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><p>完成首次接入后，建议继续阅读：</p><ul><li><a href="/connect/basics/identifiers">《标识符》</a></li><li><a href="/connect/acl/rules">《防火墙规则》</a></li><li><a href="/connect/acl/groups">《权限组》</a></li><li><a href="/connect/basics/connections">《连接机制》</a></li></ul>',44))])}const P=l(c,[["render",h]]);export{S as __pageData,P as default};
